SELECT COUNT(1)
FROM wecom_ingestion_session_day
WHERE organization_id = #{organizationId}

SELECT COUNT(1)
FROM wecom_ingestion_message
WHERE organization_id = #{organizationId}
  AND session_day_id = #{sessionKey}

SELECT

FROM wecom_ingestion_message m
JOIN wecom_ingestion_session_day s ON s.id COLLATE utf8mb4_general_ci = m.session_day_id COLLATE utf8mb4_general_ci
LEFT JOIN follow_up_record f
  ON f.id COLLATE utf8mb4_general_ci = m.follow_record_id COLLATE utf8mb4_general_ci
 AND f.organization_id COLLATE utf8mb4_general_ci = m.organization_id COLLATE utf8mb4_general_ci
WHERE m.organization_id = #{organizationId}
  AND m.session_day_id = #{sessionKey}
ORDER BY m.send_time DESC
LIMIT #{offset}, #{limit}

