mapper.select:
SELECT id FROM wecom_ingestion_session_day WHERE COALESCE(status, 'PENDING') = 'PENDING' AND (follow_record_id IS NULL OR TRIM(follow_record_id) = '') AND EXISTS ( SELECT 1 FROM wecom_ingestion_message m WHERE m.session_day_id COLLATE utf8mb4_general_ci = wecom_ingestion_session_day.id COLLATE utf8mb4_general_ci AND m.organization_id COLLATE utf8mb4_general_ci = wecom_ingestion_session_day.organization_id COLLATE utf8mb4_general_ci AND LOWER(COALESCE(m.msg_type, '')) != 'revoke' AND ( m.follow_record_id IS NULL OR TRIM(m.follow_record_id) = '' OR NOT EXISTS ( SELECT 1 FROM follow_up_record f WHERE f.id COLLATE utf8mb4_general_ci = m.follow_record_id COLLATE utf8mb4_general_ci AND f.organization_id COLLATE utf8mb4_general_ci = m.organization_id COLLATE utf8mb4_general_ci ) ) )
AND chat_date < DATE_FORMAT(CURRENT_DATE(), '%Y-%m-%d')
ORDER BY update_time ASC LIMIT #{limit}

SELECT id, organization_id, corp_id, chat_date, session_key, chat_type, external_userid, specialist_userid, roomid, first_send_time, last_send_time, message_count, media_count, merged_content, status, follow_record_id, error_message, create_user, update_user, create_time, update_time FROM wecom_ingestion_session_day WHERE COALESCE(status, 'PENDING') = 'PENDING' AND (follow_record_id IS NULL OR TRIM(follow_record_id) = '') AND EXISTS ( SELECT 1 FROM wecom_ingestion_message m WHERE m.session_day_id COLLATE utf8mb4_general_ci = wecom_ingestion_session_day.id COLLATE utf8mb4_general_ci AND m.organization_id COLLATE utf8mb4_general_ci = wecom_ingestion_session_day.organization_id COLLATE utf8mb4_general_ci AND LOWER(COALESCE(m.msg_type, '')) != 'revoke' AND ( m.follow_record_id IS NULL OR TRIM(m.follow_record_id) = '' OR NOT EXISTS ( SELECT 1 FROM follow_up_record f WHERE f.id COLLATE utf8mb4_general_ci = m.follow_record_id COLLATE utf8mb4_general_ci AND f.organization_id COLLATE utf8mb4_general_ci = m.organization_id COLLATE utf8mb4_general_ci ) ) )
AND chat_date < DATE_FORMAT(CURRENT_DATE(), '%Y-%m-%d')
ORDER BY update_time ASC LIMIT #{limit}
